public static void quickSortIterative(int[] arr, int length) {
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    stack.push(length - 1);

    while (!stack.isEmpty()) {
        int end = stack.pop();
        int start = stack.pop();
        int pivotIndex = partition(arr, start, end);

        if (pivotIndex - 1 > start) {
            stack.push(start);
            stack.push(pivotIndex - 1);
        }

